### Why is this needed?
Less double code in Cypress tests.

`cy.route` had a feature where you could do

```typescript
cy.route({
    url: '/api/foo',
    method: 'GET',
    status: 200, // <- filter by status code
}).as('fooApi');

cy.wait('@fooApi');
```

Lets say your app has request retrying implemented, in case an xhr failed. So if the first request returned `server error 500`, but the second try `ok 200`, then wait will ignore the first request due to the `status: 200` and process after the second `ok 200` request.

`cy.intercept` seems to have no replacement for that.

Solved that for now with an alternative `cy.wait` method like:

```typescript
import {Interception} from 'cypress/types/net-stubbing';
import Chainable = Cypress.Chainable;

declare global {
    namespace Cypress {
        interface Chainable<Subject> {
            waitForStatusCode(alias: string, statusCode: number): Chainable<Interception>;
            waitForStatusCodes(alias: string[], statusCode: (number | undefined)[]): Chainable<Interception>;
        }
    }
}

export function waitForStatusCode(alias: string, statusCode: number): Chainable<Interception> {
    return waitForStatusCodes([alias], [statusCode]).then((xhrs) => xhrs[0]);
}

export function waitForStatusCodes(alias: string[], statusCode: (number | undefined)[]): Chainable<Interception[]> {
    const retries = 2;
    const requestTimeout = 10000;

    function next(attempt: number): Chainable<Interception[]> {
        return cy.wait(alias, {requestTimeout}).then((xhrs: Interception | Interception[]) => {
            // if alias is an array with only one item, it'll just unwrap it and return `Interception` instead of `Interception[]`
            if (!Array.isArray(xhrs)) {
                xhrs = [xhrs];
            }

            if (!xhrs.some((xhr, index) => typeof statusCode[index] !== 'undefined' && xhr.response?.statusCode !== statusCode[index])) {
                return cy.wrap(xhrs);
            }

            if (attempt >= retries) {
                const expected = alias.map((item, index) => `${item}:${statusCode[index]}`).join(', ');
                const actual = alias.map((item, index) => `${item}:${xhrs[index]?.response?.statusCode}`).join(', ');
                const message = `Wait for status code failed. Expected: ${expected}, Actual: ${actual}`;
                throw new Error(message);
            }

            return next(attempt + 1);
        });
    }

    return next(0);
}

Cypress.Commands.add('waitForStatusCode', waitForStatusCode);
Cypress.Commands.add('waitForStatusCodes', waitForStatusCodes);
```

So 
```typescript
cy.intercept('GET', 'api/foo').as('fooApi');
cy.waitForStatusCode('@fooApi', 200)
```

lets me do exactly that.

Feel free to close this issue if this feature is out of scope for `cy.intercept` as we did the workaround already.

